"""Music-led full-length v8. Seven modes; authored sections; measured onsets."""
import math,json,bisect
from pathlib import Path
B=60/170;PHASE=.128
SPEED={1:311.58,2:387.42,3:468.0}
# Phrase boundaries are authored, not generated by cycling modes.
SCORE=[
(0,16,'cube',1,'spark'),(16,32,'robot',1,'rise'),(32,48,'ball',1,'orbit'),
(48,64,'ufo',1,'suspension'),(64,80,'ship',1,'approach'),(80,96,'spider',1,'compression'),
(96,112,'wave',2,'rupture'),(112,120,'cube',2,'impact'),(120,128,'robot',2,'rebound'),
(128,144,'ship',2,'debris'),(144,160,'ufo',2,'prism'),(160,176,'wave',2,'split'),
(176,192,'ball',2,'inversion'),(192,208,'spider',2,'fracture'),(208,224,'cube',2,'echo'),
(224,248,'ufo',1,'weightless'),(248,272,'robot',1,'ruins'),(272,288,'cube',1,'signal'),
(288,304,'wave',2,'flare'),(304,320,'ball',2,'rings'),(320,336,'ship',2,'drift'),
(336,352,'spider',1,'silence'),(352,368,'wave',3,'collapse'),(368,384,'robot',2,'shards'),
(384,400,'ship',3,'wake'),(400,416,'ufo',2,'spectrum'),(416,432,'cube',2,'ember'),
(432,448,'spider',2,'pulse'),(448,464,'ball',2,'tidal'),(464,480,'wave',3,'shear'),
(480,496,'ship',2,'magnetic'),(496,512,'robot',2,'vault'),(512,528,'ufo',2,'halo'),
(528,544,'cube',2,'retrace'),(544,560,'wave',2,'redshift'),(560,576,'ball',1,'remnant'),
(576,592,'robot',1,'ashes'),(592,608,'spider',1,'countdown'),(608,624,'wave',2,'return'),
(624,640,'ship',2,'jet'),(640,656,'ufo',2,'ion'),(656,672,'cube',1,'breath'),
(672,688,'wave',3,'supernova'),(688,704,'robot',2,'firestorm'),(704,720,'ship',3,'escape'),
(720,736,'cube',2,'afterglow')]
AUDIO=json.loads((Path(__file__).parent/'music-analysis.json').read_text())
ONSETS=AUDIO['onsets'];OTS=[o['time'] for o in ONSETS]
def bt(beat):return PHASE+beat*B if beat else 0
SECTIONS=[];cursor=0
for idx,(b0,b1,mode,speed,name) in enumerate(SCORE):
 t0,t1=bt(b0),bt(b1);v=SPEED[speed]
 SECTIONS.append(dict(index=idx,beat0=b0,beat1=b1,t0=t0,t1=t1,x0=cursor,x1=cursor+(t1-t0)*v,mode=mode,speed=v,speed_index=speed,name=name))
 cursor+=(t1-t0)*v
END=bt(736)
def section(t):return SECTIONS[max(0,min(len(SECTIONS)-1,bisect.bisect_right([s['t0'] for s in SECTIONS],t)-1))]
def xt(t):
 s=section(t);return s['x0']+(t-s['t0'])*s['speed']
def tx(x):
 s=SECTIONS[max(0,min(len(SECTIONS)-1,bisect.bisect_right([s['x0'] for s in SECTIONS],x)-1))]
 return s['t0']+(x-s['x0'])/s['speed']
def attacks(lo,hi):return ONSETS[bisect.bisect_left(OTS,lo):bisect.bisect_right(OTS,hi)]
def snap(t,radius=.12):
 options=attacks(t-radius,t+radius)
 if options:return max(options,key=lambda o:o['strength']-.5*abs(o['time']-t))['time']
 return round((t-PHASE)/(.5*B))*.5*B+PHASE

def build():
 objs=[];rects=[];hazards=[];inputs=[];orbdata=[];sections=[];paths=[];gates=[]
 def obj(oid,x,y,**kw):
  d={'1':oid,'2':round(x,5),'3':round(y,5),'20':0,'64':1,'67':1,'96':1};d.update(kw)
  o={str(k):str(v) for k,v in d.items()};objs.append(o);return o
 def rect(a,b,lo,hi,kind='platform'):
  if b-a<1 or hi-lo<1:return
  rects.append([a,b,lo,hi,kind])
  n=math.ceil((b-a)/90);m=math.ceil((hi-lo)/90)
  for i in range(n):
   for j in range(m):obj(1,a+(i+.5)*(b-a)/n,lo+(j+.5)*(hi-lo)/m,**{'128':(b-a)/n/30,'129':(hi-lo)/m/30,'135':1,'21':1,'22':1})
 def spike(x,base,up=True,scale=1):
  y=base+(15*scale if up else -15*scale)
  obj(8,x,y,**{'6':0 if up else 180,'32':scale,'135':1,'21':3})
  hazards.append(dict(x=x,y=y,base=base,up=up,scale=scale))
 def portal(oid,x,y=150):
  obj(oid,x,y,**{'128':1,'129':3.2,'13':1,'21':1004,'22':1004})
 def click(t,mode,kind='tap',**more):
  e=dict(time=round(t,6),x=xt(t),mode=mode,kind=kind);e.update(more);inputs.append(e);return e
 def sample(t,y,mode):paths.append([round(t,6),round(xt(t),5),round(y,5),mode])
 exit_y=15
 for si,orig in enumerate(SECTIONS):
  s=dict(orig);a,b,t0,t1,v=[s[k] for k in ['x0','x1','t0','t1','speed']];mode=s['mode'];first_input=len(inputs)
  s['incoming_y']=exit_y
  if si:
   portal({'cube':12,'robot':745,'ship':13,'ball':47,'ufo':111,'wave':660,'spider':1331}[mode],a+12)
   portal(10,a+55)
  if si and s['speed']!=SECTIONS[si-1]['speed']:portal({1:201,2:202,3:203}[s['speed_index']],a)
  rect(a,b,-60,0,'foundation')
  if mode in ['cube','robot']:
   # The rising platform sequence has a different contour and orb placement
   # for every phrase. Inputs are snapped to local musical attacks.
   j=0;t=snap(t0+(1.0 if si else .9));surface=0;prev_end=a
   actions=[]
   while t<t1-1.25:
    launch=xt(t);use_orb=mode=='cube' and (j+si)%4 in [1,3] and t<t1-1.5
    duration=([.075,.14,.10,.19,.055][(j+si)%5] if mode=='robot' else 0)
    click(t,mode,'hold' if mode=='robot' else 'jump',hold=duration)
    orb_t=snap(t+.20,.07) if use_orb else None
    if orb_t and not .13<orb_t-t<.30:orb_t=None
    gravity=2727.35;jump=604.8;y=surface+15;vel=jump;ts=t
    orb_kind=141 if (j+si)%4==1 else 36
    target=[30,60,0,30,0,60,30][(si+j*2)%7]
    if mode=='robot' and duration>.13:target+=30
    if orb_t:target=min(90,target+30)
    landing=None;arc=[];orb_y=None
    while ts<t+.9:
     dt=min(1/240,t+.9-ts);old=ts;ts+=dt
     g=gravity*(.18 if mode=='robot' and ts<t+duration else 1)
     y+=vel*dt-.5*g*dt*dt;vel-=g*dt
     if orb_t and old<orb_t<=ts:
      orb_y=y;vel=418.5 if orb_kind==141 else 590.85
     arc.append([ts,y])
     if vel<0 and y<=target+15 and ts-t>.15:landing=ts;break
    if landing is None:landing=t+.70
    # Wide landing face begins late enough that a jump clears its front corner.
    first_clear=next((tt for tt,yy in arc if yy>=target+18),landing)
    start_land=max(launch+v*max(.18,(landing-t)-.13),xt(first_clear)+15+v*.025)
    next_t=snap(t+([2.5,2,3,2.5,2.25,3.25][(j+si)%6]*B),.13)
    next_t=max(next_t,landing+.16)
    end_land=min(xt(t1-.48),xt(next_t)+v*.10)
    if target>0:rect(start_land,end_land,0,target,'landing')
    # Hazards occupy the ground beneath the arc, or a raised, matching plinth.
    hazard_t=t+.22;hx=xt(hazard_t)
    base=min(surface,target)
    if base>0:rect(hx-34,hx+34,0,base,'plinth')
    count=1+int((j+si)%3==2)
    for k in range(count):spike(hx+(k-(count-1)/2)*27,base,True,.85)
    if orb_y is not None:
     obj(orb_kind,xt(orb_t),orb_y,**{'21':1004,'22':1004});orbdata.append([orb_kind,xt(orb_t),orb_y])
     click(orb_t,mode,'orb',orb_id=orb_kind)
    for tt,yy in arc:sample(tt,max(target+15,yy) if tt>=landing else yy,mode)
    actions.append(dict(time=t,source=surface,target=target,landing=landing,next=next_t,orb_time=orb_t,hold=duration))
    sample(next_t,target+15,mode)
    surface=target;t=next_t;j+=1
   # Clear tail provides time to settle to the next mode's baseline.
   s['actions']=actions;exit_y=15
  elif mode in ['ball','spider']:
   t=snap(t0+.95);flip=0;floor=True;surface=0;events=[]
   while t<t1-1.5:
    events.append(t)
    spacing=([2.25,2.75,2,3,2.5,2.25,3.25] if mode=='ball' else [1.5,2.5,2,1.75,2.75,1.5,2.25])[(si+flip)%7]
    nt=snap(t+spacing*B,.13);t=max(nt,t+(.64 if mode=='ball' else .43));flip+=1
   rails=[]
   for j,t in enumerate(events):
    lower=j%2==1;target=([0,30,60,0][(j+si)%4] if lower else [240,270,210,300][(j+si)%4])
    nxt=events[j+1] if j+1<len(events) else t1-.6
    left=xt(t)-28 if mode=='spider' else xt(t)+v*.12
    right=min(b,xt(nxt)+v*.10)
    if lower:
     if target>0:rect(left,right,0,target,'lower island')
    else:rect(left,right,target,390,'hanging island')
    # The player's old rail has a hazard after the switch. Add a small support
    # to that old rail where needed, instead of leaving floating spikes.
    sx=xt(t)+v*(.26 if mode=='ball' else .18)
    if floor:
     if surface>0:rect(sx-25,sx+25,0,surface,'hazard support')
     spike(sx,surface,True,.9)
    else:
     rect(sx-25,sx+25,surface,390,'hazard support');spike(sx,surface,False,.9)
    click(t,mode,'flip',from_floor=floor,target_y=target)
    rails.append(dict(time=t,from_surface=surface,to_surface=target,from_floor=floor,next=nxt))
    surface=target;floor=not floor
   s['flips']=rails
   portal(10,b-v*.68)
   exit_y=15
  else:
   # Free flight through open rooms. Obstacles are discrete masses with broad
   # openings; no repeated sawtooth tunnel is used anywhere in this score.
   rect(a,b,330,390,'ceiling')
   local=[];start_y=max(20,min(280,s['incoming_y']));y=start_y;t=t0;vel=0
   if mode=='wave':
    direction=1 if y<170 else -1;click(t0+.04,mode,'hold',down=direction>0)
    turns=[]
    while t<t1-.20:
     lo=t+.25;hi=min(t+.68,t1)
     options=attacks(lo,hi)
     candidates=[]
     for o in options:
      yy=y+direction*v*(o['time']-t)
      if 55<=yy<=280:candidates.append((o['strength']-abs(yy-(245 if direction>0 else 85))*.0015,o['time'],yy))
     if candidates:_,nt,ny=max(candidates)
     else:
      distance=((240 if direction>0 else 85)-y)/direction
      nt=min(t1,max(t+.18,t+distance/v));ny=y+direction*v*(nt-t)
     if nt>t1-.20:
      nt=t1;ny=y+direction*v*(nt-t)
     if not 25<ny<310:
      nt=min(t1,t+max(.08,((275 if direction>0 else 55)-y)/(direction*v)));ny=y+direction*v*(nt-t)
     for k in range(max(1,math.ceil((nt-t)*120))):
      tt=t+(nt-t)*k/max(1,math.ceil((nt-t)*120));local.append([tt,y+direction*v*(tt-t)])
     t,y=nt,ny
     if t<t1-.001:direction*=-1;turns.append(t);click(t,mode,'turn',down=direction>0)
    if t<t1:
     local.append([t1,max(25,min(305,y+direction*v*(t1-t)))]);y=local[-1][1]
    s['turns']=turns
   elif mode=='ufo':
    t=t0;vel=0;next_click=snap(t0+.16,.06);jump=330;gravity=1200
    while t<t1:
     dt=min(1/240,t1-t)
     if t>=next_click and y>230:next_click=t+.08
     if t>=next_click:
      vel=jump;click(t,mode,'hop')
      opts=attacks(t+.30,min(t+.62,t1))
      target=145+50*math.sin((t-t0)/(t1-t0)*math.pi*1.7+si)
      good=[(o['strength']-.003*abs(y+jump*(o['time']-t)-gravity/2*(o['time']-t)**2-target),o['time']) for o in opts]
      next_click=max(good)[1] if good else t+.50
     y+=vel*dt-.5*gravity*dt*dt;vel-=gravity*dt;t+=dt
     if y<15:y=15;vel=0
     if y>290:next_click=max(next_click,t+.50)
     local.append([t,y])
   else:
    down=False;next_control=t0;last=-1
    while t<t1:
     target=155+45*math.sin((t-t0)/(t1-t0)*math.pi*1.8+si*.7)
     if t>=next_control:
      choose=target-y-vel*.19>0
      if choose!=down or last<0:down=choose;click(t,mode,'thrust',down=down);last=t
      opts=attacks(t+.22,min(t+.36,t1));next_control=max(opts,key=lambda o:o['strength'])['time'] if opts else t+.27
     dt=min(1/240,t1-t);acc=1000*(1 if down else -1)
     y+=vel*dt+.5*acc*dt*dt;vel=max(-300,min(300,vel+acc*dt));t+=dt
     if y+vel*abs(vel)/2000<48 and not down:down=True;next_control=t+.23;click(t,mode,'thrust',down=True)
     if y+vel*abs(vel)/2000>282 and down:down=False;next_control=t+.23;click(t,mode,'thrust',down=False)
     local.append([t,y])
   # Place 3-5 architectural gates on strong attacks. Each is individually
   # fitted to the route, leaving asymmetric rooms between them.
   lt=[p[0] for p in local]
   gate_t=t0+1.15;gi=0
   while gate_t<t1-.7:
    gt=snap(gate_t,.14);ix=max(0,min(len(local)-1,bisect.bisect_left(lt,gt)));cy=local[ix][1]
    gap=142 if mode=='wave' else 186 if mode=='ufo' else 200
    w=[45,75,30,60,90][(gi+si)%5];gx=xt(gt)
    # Both edges account for the finite width of a gate and the local slope.
    nearby=[p[1] for p in local if abs(xt(p[0])-gx)<w/2+20]
    low=max(0,min(nearby or [cy])-gap/2);high=min(330,max(nearby or [cy])+gap/2)
    if gi%3!=1 and low>8:rect(gx-w/2,gx+w/2,0,low,'flight pillar')
    if gi%3!=2 and high<322:rect(gx-w/2,gx+w/2,high,390,'flight pendant')
    gates.append(dict(x=gx,time=gt,low=low,high=high,width=w,mode=mode))
    gate_t+=([2.5,3.5,2,3,4][(si+gi)%5])*B;gi+=1
   for tt,yy in local:sample(tt,yy,mode)
   exit_y=max(20,min(280,y));s['flight_points']=local
  s['input_count']=len(inputs)-first_input;sections.append(s)
 # Free camera and fixed vertical framing; all seven modes share clear limits.
 obj(2925,0,-450,**{'111':1,'112':1,'113':10,'114':.5,'370':1,'20':5})
 obj(1764,0,150,**{'57':900,'121':1,'134':1,'128':.01,'129':.01,'21':60,'22':60,'24':-5})
 obj(1913,0,-450,**{'371':.90,'10':0,'20':5})
 obj(1914,1,-450,**{'71':900,'101':2,'155':1,'10':0,'20':5})
 obj(3600,xt(END),150,**{'20':5})
 return objs,dict(sections=sections,speed_schedule=[[s['t0'],s['speed']] for s in sections],beat=B,phase=PHASE,
  drop_time=bt(96),end_time=END,end_x=xt(END),rectangles=rects,hazards=hazards,
  controls=sorted(inputs,key=lambda e:e['time']),orbs=orbdata,gates=gates,paths=paths,camera_y=150,camera_zoom=.9,initial_mode='cube')
if __name__=='__main__':
 o,p=build();Path('work/full-plan.json').write_text(json.dumps(p,indent=2));print('objects',len(o),'seconds',END,'sections',len(p['sections']),'inputs',len(p['controls']))
